module freq_divbyfrac (
    input  wire clk,
    input  wire rst_n,
    output wire clk_div
);

    localparam CNT_MAX = 7; // counts 0..6

    reg [2:0] cnt;

    // clk_pos high for cnt = 0..3, low otherwise
    reg clk_pos;

    // clk_pos sampled at negedge clk -> clk_pos_neg_raw
    reg clk_pos_neg_raw;
    // Two-stage synchronizer to align clk_pos_neg_raw to posedge clk domain
    reg clk_pos_neg_sync1, clk_pos_neg_sync2;
    // Phase shifted clock generated by synchronized negedge sampled signal
    reg clk_neg;

    // Counter and clk_pos generation - synchronous reset on posedge clk
    always @(posedge clk) begin
        if (!rst_n) begin
            cnt <= 3'd0;
            clk_pos <= 1'b0;
        end else begin
            if (cnt == CNT_MAX - 1)
                cnt <= 3'd0;
            else
                cnt <= cnt + 3'd1;

            // clk_pos high for counts 0..3 (4 cycles), low for 4..6 (3 cycles)
            if (cnt <= 3'd3)
                clk_pos <= 1'b1;
            else
                clk_pos <= 1'b0;
        end
    end

    // Sample clk_pos on negedge clk, asynchronous to clk domain
    always @(negedge clk or negedge rst_n) begin
        if (!rst_n)
            clk_pos_neg_raw <= 1'b0;
        else
            clk_pos_neg_raw <= clk_pos;
    end

    // Synchronize clk_pos_neg_raw into posedge clk domain (2-flip flop synchronizer)
    always @(posedge clk) begin
        if (!rst_n) begin
            clk_pos_neg_sync1 <= 1'b0;
            clk_pos_neg_sync2 <= 1'b0;
        end else begin
            clk_pos_neg_sync1 <= clk_pos_neg_raw;
            clk_pos_neg_sync2 <= clk_pos_neg_sync1;
        end
    end

    // Assign phase shifted clk_neg from synchronized negedge sampled signal
    always @(posedge clk) begin
        if (!rst_n)
            clk_neg <= 1'b0;
        else
            clk_neg <= clk_pos_neg_sync2;
    end

    // Final output is OR of clk_pos and clk_neg
    assign clk_div = clk_pos | clk_neg;

endmodule